from rich.traceback import Traceback
from rich.console import Console

def test_exception_notes():
    try:
        try:
            raise ValueError("Original error")
        except ValueError as e:
            e.add_note("Note 1")
            e.add_note("Note 2")
            raise
    except Exception:
        console = Console()
        console.print(Traceback.from_exception(ValueError, ValueError("Original error"), None))
        # Wait, from_exception takes the actual exception.
        # Let's just use a real exception.

def test_real_exception():
    try:
        try:
            raise ValueError("Original error")
        except ValueError as e:
            e.add_note("Note 1")
            e.add_note("Note 2")
            raise
    except Exception as e:
        console = Console()
        console.print(Traceback.from_exception(type(e), e, e.__traceback__))

if __name__ == "__main__":
    test_real_exception()

